function Invoke-UserManagementSmokeTests { param([string]$Username="",[string]$Password="")
    if(-not$Username-or-not$Password){Write-TestSkipped "User management tests";return};$login=Invoke-ApiRequest "POST" "/api/v1/auth/login" -Body @{username=$Username;password=$Password};if($login.StatusCode-ne 200){Write-TestSkipped "User management tests";return};$headers=@{Authorization="Bearer $((Convert-JsonResponse $login 'User management login contains valid JSON').token)"};$users=Invoke-ApiRequest "GET" "/api/v1/users" -Headers $headers;if(-not(Assert-StatusCode $users 200 "Administrator can list users")){return};$list=Convert-JsonResponse $users "Users response contains valid JSON";if($null-ne$list.data-and$null-ne$list.meta.total){Write-TestSuccess "Users response follows the V1 contract"}else{Write-TestFailure "Users response follows the V1 contract"};$me=Invoke-ApiRequest "GET" "/api/v1/me" -Headers $headers;$current=(Convert-JsonResponse $me "Current user response contains valid JSON").data;$detail=Invoke-ApiRequest "GET" "/api/v1/users/$($current.id)" -Headers $headers;if(Assert-StatusCode $detail 200 "Administrator can view a user"){if((Convert-JsonResponse $detail "User detail contains valid JSON").data.username-eq$current.username){Write-TestSuccess "User detail follows the V1 contract"}else{Write-TestFailure "User detail follows the V1 contract"}};$roles=@($current.roles);$update=Invoke-ApiRequest "PATCH" "/api/v1/users/$($current.id)" -Headers $headers -Body @{roles=$roles};if(Assert-StatusCode $update 403 "Administrator cannot change own roles"){Assert-ApiError $update "FORBIDDEN" "Own role protection follows the error contract"}
}
